async function fetchUnsplashAndUpload(query, slug) {
  // Поиск фото на Unsplash
  const searchUrl = new URL("https://api.unsplash.com/search/photos");
  searchUrl.searchParams.set("query", query);
  searchUrl.searchParams.set("per_page", "5");
  searchUrl.searchParams.set("orientation", "landscape");

  const searchRes = await fetch(searchUrl, {
    headers: { Authorization: `Client-ID ${UNSPLASH}` },
  });
  if (!searchRes.ok) {
    console.warn(`  unsplash search failed: ${searchRes.status}`);
    return null;
  }
  const searchJson = await searchRes.json();
  const photo = searchJson.results?.[0];
  if (!photo) {
    console.warn(`  no photo found for: ${query}`);
    return null;
  }

  // Скачиваем фото
  const imgUrl = photo.urls.raw + "&w=1200&q=80&fm=jpg";
  const imgRes = await fetch(imgUrl);
  if (!imgRes.ok) {
    console.warn(`  image download failed: ${imgRes.status}`);
    return null;
  }
  const imgBuf = Buffer.from(await imgRes.arrayBuffer());

  // Загружаем в Supabase Storage
  const hash = crypto.createHash("md5").update(slug).digest("hex").slice(0, 12);
  const storagePath = `u/${hash}.jpg`;

  const { error: uploadError } = await sb.storage
    .from("photos")
    .upload(storagePath, imgBuf, {
      contentType: "image/jpeg",
      upsert: true,
    });

  if (uploadError) {
    console.warn(`  storage upload failed: ${uploadError.message}`);
    // Возвращаем raw URL как fallback
    return photo.urls.raw;
  }

  const publicUrl = `${SUPA_URL}/storage/v1/object/public/photos/${storagePath}`;
  console.log(`  cover uploaded → ${publicUrl}`);
  return publicUrl;
}

function parseFrontmatter(content) {
  const match = content.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!match) {
    // Если нет frontmatter — возвращаем весь контент как body
    return { fm: {}, body: content.trim() };
  }
  const fm = {};
  for (const line of match[1].split("\n")) {
    const colon = line.indexOf(":");
    if (colon === -1) continue;
    const key = line.slice(0, colon).trim();
    const val = line.slice(colon + 1).trim().replace(/^"(.*)"$/, "$1");
    fm[key] = val;
  }
  const body = match[2].trim();
  return { fm, body };
}

async function run() {
  const base = Date.now();
  let added = 0;
  let skipped = 0;
  let errors = 0;

  console.log(`\n=== Seed: 10 СИЛЬНЫХ SEO-статей ===\n`);

  for (let i = 0; i < ARTICLES.length; i++) {
    const article = ARTICLES[i];
    const { slug, title, description, tag, unsplash_query, country_slug, city_slug } = article;

    const filePath = path.join(BLOG_DIR, `${slug}.md`);

    if (!fs.existsSync(filePath)) {
      console.error(`[${i + 1}/${ARTICLES.length}] FILE NOT FOUND: ${slug}.md — skip`);
      errors++;
      continue;
    }

    // Проверяем, нет ли уже такого slug в базе
    const { data: existing } = await sb
      .from("blog_posts")
      .select("id")
      .eq("slug", slug)
      .maybeSingle();

    if (existing) {
      console.log(`[${i + 1}/${ARTICLES.length}] skip (exists in DB): ${slug}`);
      skipped++;
      continue;
    }

    console.log(`[${i + 1}/${ARTICLES.length}] Processing: ${slug}`);

    // Читаем файл
    const raw = fs.readFileSync(filePath, "utf8");
    let fm, body;
    try {
      ({ fm, body } = parseFrontmatter(raw));
    } catch (e) {
      console.error(`  parse error: ${e.message}`);
      errors++;
      continue;
    }

    // Загружаем обложку
    let coverUrl = null;
    try {
      coverUrl = await fetchUnsplashAndUpload(unsplash_query, slug);
    } catch (e) {
      console.warn(`  cover error: ${e.message}`);
    }

    // Разносим created_at по часу для правильного порядка в блоге
    const createdAt = new Date(base - i * 3600 * 1000).toISOString();

    const row = {
      title: title,
      slug: slug,
      tag: tag,
      content_md: body,
      seo_title: title,
      seo_description: description,
      country_slug: country_slug ?? null,
      city_id: null,
      cover_url: coverUrl ?? null,
      published: true,
      created_at: createdAt,
    };

    const { error: insertError } = await sb.from("blog_posts").insert(row);
    if (insertError) {
      console.error(`  insert error: ${insertError.message}`);
      errors++;
      continue;
    }

    added++;
    console.log(`  + added${coverUrl ? " (with cover)" : " (no cover)"}`);

    // Небольшая пауза, чтобы не выбить лимит Unsplash API (50 req/hour для free)
    if (i < ARTICLES.length - 1) {
      await new Promise((r) => setTimeout(r, 1200));
    }
  }

  console.log(`\n=== DONE ===`);
  console.log(`added:   ${added}`);
  console.log(`skipped: ${skipped}`);
  console.log(`errors:  ${errors}`);
  console.log(`total:   ${ARTICLES.length}`);
}

run().catch((e) => {
  console.error("Fatal:", e);
  process.exit(1);
});
